const fs = require('fs');
const repo = $env.AGENT_REPO_PATH || '/data/repo';
const yaml = fs.readFileSync(`${repo}/config/channels.yaml`, 'utf8');
const map = {}; let cur = null;
for (const raw of yaml.split('\n')) {
  const line = raw.replace(/\s+#.*$/, '');
  const mNew = line.match(/^\s*-\s+id:\s*(.+?)\s*$/);
  if (mNew) { cur = mNew[1].trim(); map[cur] = {}; continue; }
  if (!cur) continue;
  const kv = line.match(/^\s*(platform|publishWorkflow|enabled):\s*(.+?)\s*$/);
  if (kv) map[cur][kv[1]] = kv[2].replace(/^["']|["']$/g, '');
}
const input = $input.first().json;
const approved = input.approved === true;
const scheduled = input.scheduled || [];
const out = [];
for (const item of scheduled) {
  const ch = map[item.channel] || {};
  if (!ch.publishWorkflow) continue;          // 未定義channelはスキップ
  if (String(ch.enabled) !== 'true') continue; // 無効channelは投稿しない
  out.push({ json: { workflowPath: `${repo}/${ch.publishWorkflow}`, platform: ch.platform, channel: item.channel, approved, scheduled: [item] } });
}
return out;
